cat >> lib/dates.ts <<'EOF'

/**
 * The offset of a zone from UTC at a given instant, in milliseconds.
 * Derived from the formatter rather than a table, so it follows daylight saving.
 */
function zoneOffsetMilliseconds(timeZone: string, instant: Date): number {
    const parts = new Intl.DateTimeFormat('en-US', {
        timeZone,
        hour12: false,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
    }).formatToParts(instant);
    const valueOf = (type: string) => Number(parts.find(part => part.type === type)?.value);

    const asIfUtc = Date.UTC(
        valueOf('year'),
        valueOf('month') - 1,
        valueOf('day'),
        // Some engines report midnight as hour 24.
        valueOf('hour') % 24,
        valueOf('minute'),
        valueOf('second'),
    );

    return asIfUtc - (instant.getTime() - instant.getMilliseconds());
}

/**
 * Milliseconds until the calendar day rolls over at the origin airport.
 *
 * A page left open across the origin's midnight has to refresh the dates it
 * offers. Tokyo rolls over at 15:00 UTC and Los Angeles at 07:00 or 08:00, so a
 * UTC-midnight timer would leave the picker stale for most of a day.
 *
 * Without a zone this is the UTC day boundary.
 */
export function millisecondsUntilNextLocalDay(
    originTimeZone?: string | null,
    referenceDate = new Date(),
): number {
    const offset = originTimeZone ? zoneOffsetMilliseconds(originTimeZone, referenceDate) : 0;
    const local = new Date(referenceDate.getTime() + offset);
    const nextLocalMidnight = Date.UTC(
        local.getUTCFullYear(),
        local.getUTCMonth(),
        local.getUTCDate() + 1,
    );

    return nextLocalMidnight - offset - referenceDate.getTime();
}
EOF
cat >> __tests__/lib/dates.test.ts <<'EOF'

describe('millisecondsUntilNextLocalDay', () => {
    const anHour = 60 * 60 * 1000;

    it('counts to the UTC day boundary when no origin zone is known', () => {
        expect(millisecondsUntilNextLocalDay(undefined, new Date('2026-06-25T23:00:00Z')))
            .toBe(anHour);
    });

    it('counts to the origin airport midnight, not the UTC one', () => {
        // 14:00 UTC is 23:00 in Tokyo, so the day rolls over in an hour there
        // but not for another ten hours in UTC.
        expect(millisecondsUntilNextLocalDay('Asia/Tokyo', new Date('2026-06-25T14:00:00Z')))
            .toBe(anHour);
        // 06:00 UTC is 23:00 the previous evening in Los Angeles on PDT.
        expect(millisecondsUntilNextLocalDay('America/Los_Angeles', new Date('2026-06-25T06:00:00Z')))
            .toBe(anHour);
    });

    it('follows daylight saving rather than a fixed offset', () => {
        // New York is UTC-4 on EDT and UTC-5 on EST, so the same UTC clock time
        // sits a different distance from local midnight.
        expect(millisecondsUntilNextLocalDay('America/New_York', new Date('2026-07-01T03:00:00Z')))
            .toBe(anHour);
        expect(millisecondsUntilNextLocalDay('America/New_York', new Date('2026-01-01T04:00:00Z')))
            .toBe(anHour);
    });

    it('always lands within the coming day', () => {
        for (const zone of ['Asia/Tokyo', 'America/Los_Angeles', 'Europe/London', 'America/Sao_Paulo']) {
            const remaining = millisecondsUntilNextLocalDay(zone, new Date('2026-06-25T12:34:56Z'));
            expect(remaining).toBeGreaterThan(0);
            expect(remaining).toBeLessThanOrEqual(24 * anHour);
        }
    });
});
