import bcrypt from 'bcryptjs';
import { prisma } from './lib/prisma';

const MARK = 'UIREVIEW';

async function main() {
    const email = 'uireview-local@example.com';
    await prisma.user.deleteMany({ where: { email } });
    await prisma.user.create({
        data: { name: 'UI Review', email, password: await bcrypt.hash('Password123!', 10), emailVerified: new Date() },
    });

    // The default route the form opens on.
    const outbound = await prisma.flight.findFirstOrThrow({
        where: { departureDate: { gt: new Date() } },
        orderBy: { departureDate: 'asc' },
    });
    const returnDay = new Date(outbound.departureDate);
    returnDay.setUTCDate(returnDay.getUTCDate() + 7);

    // Two return options so the selection UI has something to choose between.
    await prisma.flight.deleteMany({ where: { flightNumber: { startsWith: MARK } } });
    for (const [i, spec] of [['09:00', '$275'], ['17:30', '$310']].entries()) {
