        const dep = new Date(returnDay);
        dep.setUTCHours(Number(time.split(':')[0]), Number(time.split(':')[1]), 0, 0);
        await prisma.flight.create({
            data: {
                flightNumber: `${MARK}${90 + i}`,
                airline: i === 0 ? 'Gemini Airways' : 'United Airlines',
                from: outbound.to,
                to: outbound.from,
                departureDate: dep,
                price,
                status: 'ON_TIME',
                firstClassRows: outbound.firstClassRows,
                businessRows: outbound.businessRows,
                premiumEconomyRows: outbound.premiumEconomyRows,
                economyRows: outbound.economyRows,
                seatPattern: outbound.seatPattern,
            },
        });
