                                            leg?.seatAssignments?.find(seat => seat.passengerId === passengerId)?.seatNumber
                                            ?? fallback
                                        );
                                    return (
                                        <tbody key={booking.id} data-testid={`booking-row-${booking.id}`} className="border-b">
                                            {legRows.map((leg, index) => (
                                                <tr
                                                    key={leg?.flight?.id ?? index}
                                                    data-testid={`booking-leg-${booking.id}-${index}`}
                                                    className={index === legRows.length - 1 ? 'border-b' : undefined}
                                                >
                                                    <td className="py-2 pr-6">
                                                        {index === 0 && (
                                                            <div style={{ fontSize: '0.7rem', color: '#a78bfa', textTransform: 'uppercase', letterSpacing: '0.04em' }}>
                                                                {legs.length > 1 ? 'Round trip' : 'One way'}
                                                            </div>
                                                        )}
                                                        <div>{leg?.flight ? `${leg.flight.airline} ${leg.flight.flightNumber}` : '\\u2014'}</div>
                                                        {booking.passengers && booking.passengers.length > 0 && (
                                                            <div style={{ fontSize: '0.75rem', color: 'rgba(255,255,255,0.4)', marginTop: '2px' }}>
                                                                {booking.passengers
                                                                    .map(p => `${p.firstName} (${seatFor(leg, p.id, p.seatNumber)})`)
                                                                    .join(', ')}
                                                            </div>
                                                        )}
                                                    </td>
                                                    <td className="py-2 pr-6">{leg?.flight ? `${leg.flight.from} \\u2192 ${leg.flight.to}` : '\\u2014'}</td>
                                                    <td className="py-2 pr-6 whitespace-nowrap">{leg?.flight ? new Date(leg.flight.departureDate).toLocaleDateString() : '\\u2014'}</td>
                                                    {index === 0 && (
                                                        <>
                                                            <td className="py-2 pr-6 whitespace-nowrap align-top" rowSpan={legRows.length}>{
                                                                booking.totalPriceCents !== null && booking.totalPriceCents !== undefined
                                                                    ? formatPrice(booking.totalPriceCents)
                                                                    : legs[0]?.flight?.price ?? '\\u2014'
                                                            }</td>
                                                            <td className="py-2 pr-6 align-top" rowSpan={legRows.length}>
                                                                <span style={{
                                                                    color: isCancelled ? '#ef4444' : '#10b981',
                                                                    fontWeight: 'bold',
                                                                    fontSize: '0.85rem'
                                                                }}>
                                                                    {isCancelled ? 'Cancelled' : 'Confirmed'}
                                                                </span>
                                                            </td>
                                                            <td className="py-2 text-right align-top" rowSpan={legRows.length}>
                                                                {!isCancelled && (
                                                                    <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
                                                                        <button
                                                                            onClick={() => setSelectedBooking(booking)}
                                                                            disabled={isPending}
                                                                            style={{
                                                                                backgroundColor: '#8b5cf6',
                                                                                color: 'white',
                                                                                padding: '4px 8px',
                                                                                borderRadius: '4px',
                                                                                fontSize: '12px',
                                                                                height: 'auto',
                                                                                width: 'auto',
                                                                                cursor: 'pointer',
                                                                                whiteSpace: 'nowrap'
                                                                            }}
                                                                        >
                                                                            Change Seats
                                                                        </button>
                                                                        <button
                                                                            onClick={() => handleCancelBooking(booking.id, legs[0]?.flight?.flightNumber || '')}
                                                                            disabled={isPending}
                                                                            style={{
                                                                                backgroundColor: '#ef4444',
                                                                                color: 'white',
                                                                                padding: '4px 8px',
                                                                                borderRadius: '4px',
                                                                                fontSize: '12px',
                                                                                height: 'auto',
                                                                                width: 'auto',
                                                                                cursor: 'pointer'
                                                                            }}
                                                                        >
                                                                            Cancel
                                                                        </button>
                                                                    </div>
                                                                )}
                                                            </td>
                                                        </>
                                                    )}
                                                </tr>
                                            ))}
                                        </tbody>
                                    );
                                })}
'''
s = s[:old_start] + new + s[old_end + len("                                </tbody>\n"):]
p.write_text(s)
print("restructured")
